-- PsyLab V52 — migration Fauteuil Clinique
-- Run AFTER supabase_v51_migration.sql.
-- Replaces the generic weekly MCQ with a progressive five-decision clinical case.

insert into public.challenge_templates(template_id,course_key,content,answer_key,max_score) values (1,'bipolar','{"fr":{"title":"Le lien temporel","intro":"Une patiente de 49 ans, sans antécédent thymique clairement documenté, présente depuis huit jours une activation inhabituelle : sommeil réduit sans fatigue, parole plus abondante, projets multiples, irritabilité et dépenses inhabituelles. Un traitement systémique susceptible d’induire une activation a été introduit dix jours avant le début des symptômes.","steps":[{"kind":"multi","label":"Première impression","prompt":"Quelles deux hypothèses doivent rester en tête avant de conclure ?","choices":["Syndrome thymique induit par un médicament","Trouble anxieux réactionnel isolé","Épisode maniaque primaire","TDAH ancien décompensé"],"required":2,"max":2,"competency":"n2.branching","score_weight":20},{"kind":"single","label":"Donnée discriminante","new_data":"La famille confirme l’absence d’épisode comparable antérieur. Les symptômes ont débuté après l’introduction du traitement.","prompt":"Quelle information ferait le plus bouger la hiérarchie entre cause médicamenteuse et trouble bipolaire primaire ?","choices":["La présence d’irritabilité","La persistance du syndrome au-delà de l’effet physiologique attendu du traitement","Le fait qu’elle parle davantage","L’existence d’un stress professionnel"],"competency":"n2.causality","score_weight":20},{"kind":"single","label":"Question stratégique","new_data":"Le traitement est en cours de réduction selon l’équipe somatique.","prompt":"Quelle donnée faut-il prioritairement documenter au suivi ?","choices":["La couleur habituelle de ses vêtements","L’évolution de l’activation après diminution puis disparition attendue de l’effet du traitement","Son niveau scolaire","Le nombre de cafés bus avant midi"],"competency":"n2.information","score_weight":20},{"kind":"single","label":"Contre-hypothèse","prompt":"Quelle est l’alternative diagnostique la plus solide à défendre tant que l’évolution n’est pas connue ?","choices":["Trouble bipolaire I avec épisode maniaque primaire","Trouble panique","Trouble obsessionnel-compulsif","Trouble neurocognitif majeur"],"competency":"n2.differential","score_weight":15},{"kind":"final","label":"Conclusion","new_data":"À ce stade, aucun épisode thymique indépendant antérieur n’est retrouvé et la relation temporelle avec le traitement est étroite. La persistance autonome n’est pas encore connue.","prompt":"Formulez la conclusion la plus défendable aujourd’hui.","diagnoses":["Trouble bipolaire I certain","Syndrome anxieux réactionnel","Trouble bipolaire et apparenté induit par un médicament, hypothèse actuellement la plus soutenue","Aucun syndrome thymique"],"arguments":["La seule présence d’irritabilité","La relation temporelle exposition → activation, sans épisode indépendant documenté, avec nécessité d’observer la persistance","Le nombre de projets entrepris","L’âge de la patiente"],"competency":"n2.formulation","score_weight":25}]},"en":{"title":"The temporal link","intro":"A 49-year-old patient with no clearly documented prior mood episode has eight days of unusual activation: reduced sleep without fatigue, increased speech, multiple projects, irritability and unusual spending. A systemic treatment capable of provoking activation was introduced ten days before symptoms began.","steps":[{"kind":"multi","label":"First impression","prompt":"Which two hypotheses should remain active before closure?","choices":["Medication-induced mood syndrome","Isolated reactive anxiety","Primary manic episode","Longstanding ADHD decompensation"],"required":2,"max":2,"competency":"n2.branching","score_weight":20},{"kind":"single","label":"Discriminating datum","new_data":"Family confirms no similar previous episode. Symptoms began after the treatment was introduced.","prompt":"Which information would most change the hierarchy between medication causality and primary bipolar disorder?","choices":["Presence of irritability","Persistence beyond the treatment’s expected physiological effect","Increased speech","Work stress"],"competency":"n2.causality","score_weight":20},{"kind":"single","label":"Strategic question","new_data":"The medical team is tapering the treatment.","prompt":"What should be documented first during follow-up?","choices":["Usual clothing color","Course of activation after dose reduction and expected disappearance of the treatment effect","Educational level","Number of morning coffees"],"competency":"n2.information","score_weight":20},{"kind":"single","label":"Counter-hypothesis","prompt":"What is the strongest competing diagnosis while the subsequent course remains unknown?","choices":["Bipolar I disorder with a primary manic episode","Panic disorder","Obsessive-compulsive disorder","Major neurocognitive disorder"],"competency":"n2.differential","score_weight":15},{"kind":"final","label":"Conclusion","new_data":"So far, no independent previous mood episode has been identified and the temporal relationship with treatment is close. Independent persistence is not yet known.","prompt":"Choose the most defensible conclusion today.","diagnoses":["Definite bipolar I disorder","Reactive anxiety syndrome","Medication-induced bipolar and related disorder is currently the leading hypothesis","No mood syndrome"],"arguments":["Irritability alone","Exposure-to-activation temporal relationship, no documented independent episode, and the need to observe persistence","Number of projects","Patient age"],"competency":"n2.formulation","score_weight":25}]}}'::jsonb,'{"steps":[{"kind":"multi","correct":[0,2],"weight":20,"calibration":4},{"kind":"single","correct":1,"weight":20,"calibration":4},{"kind":"single","correct":1,"weight":20,"calibration":4},{"kind":"single","correct":0,"weight":15,"calibration":3},{"kind":"final","diagnosis":2,"argument":1,"certainty_target":70,"weight":25}]}'::jsonb,100) on conflict(template_id) do update set course_key=excluded.course_key,content=excluded.content,answer_key=excluded.answer_key,max_score=excluded.max_score;

insert into public.challenge_templates(template_id,course_key,content,answer_key,max_score) values (2,'bipolar','{"fr":{"title":"L’épisode oublié","intro":"Une patiente de 31 ans consulte pour un épisode dépressif caractérisé. Au cours de l’anamnèse longitudinale, elle décrit une période ancienne de cinq jours nettement différente de son fonctionnement habituel.","steps":[{"kind":"multi","label":"Première impression","prompt":"Quelles deux architectures diagnostiques doivent être comparées en priorité ?","choices":["Dépression unipolaire","Trouble bipolaire II","Trouble bipolaire I","Trouble délirant"],"required":2,"max":2,"competency":"n2.branching","score_weight":20},{"kind":"single","label":"Nouvelle donnée","new_data":"Pendant ces cinq jours : besoin de sommeil diminué, énergie accrue, sociabilité inhabituelle et multiplication des projets. L’entourage avait remarqué le changement, mais il n’y avait ni psychose, ni hospitalisation, ni altération fonctionnelle marquée.","prompt":"Quel seuil syndromique cette description soutient-elle le mieux ?","choices":["Hypomanie passée","Manie passée","Simple bien-être","Épisode mixte actuel"],"competency":"n2.threshold","score_weight":20},{"kind":"single","label":"Question stratégique","prompt":"Quelle question a la plus grande valeur pour éviter une mauvaise classification ?","choices":["A-t-elle déjà eu une période avec altération fonctionnelle marquée, psychose ou hospitalisation liée à une activation ?","Préfère-t-elle travailler le matin ?","Aime-t-elle les voyages ?","A-t-elle déjà eu une semaine chargée ?"],"competency":"n2.information","score_weight":20},{"kind":"single","label":"Contre-hypothèse","new_data":"Aucun épisode maniaque n’est retrouvé malgré une anamnèse détaillée et des informations collatérales.","prompt":"Quelle hypothèse concurrente devient nettement moins probable ?","choices":["Trouble bipolaire I","Trouble bipolaire II","Épisode dépressif majeur","Hypomanie passée"],"competency":"n2.differential","score_weight":15},{"kind":"final","label":"Conclusion","prompt":"Quelle synthèse longitudinale est la plus solide ?","diagnoses":["Trouble dépressif majeur récurrent","Trouble bipolaire II","Trouble bipolaire I","Cyclothymie"],"arguments":["Dépression actuelle uniquement","Épisode dépressif majeur + hypomanie passée caractérisée + absence de manie retrouvée","Présence de fatigue","Labilité émotionnelle quotidienne"],"competency":"n2.formulation","score_weight":25}]},"en":{"title":"The forgotten episode","intro":"A 31-year-old patient presents with a major depressive episode. During longitudinal history-taking she describes a previous five-day period clearly different from her usual functioning.","steps":[{"kind":"multi","label":"First impression","prompt":"Which two diagnostic architectures should be compared first?","choices":["Unipolar depression","Bipolar II disorder","Bipolar I disorder","Delusional disorder"],"required":2,"max":2,"competency":"n2.branching","score_weight":20},{"kind":"single","label":"New information","new_data":"During those five days she had reduced need for sleep, increased energy, unusual sociability and multiple projects. Others noticed the change, but there was no psychosis, hospitalization or marked functional impairment.","prompt":"Which syndromic threshold is best supported?","choices":["Past hypomania","Past mania","Simple well-being","Current mixed episode"],"competency":"n2.threshold","score_weight":20},{"kind":"single","label":"Strategic question","prompt":"Which question has the highest information value for avoiding misclassification?","choices":["Has there ever been activation with marked functional impairment, psychosis or hospitalization?","Does she prefer working in the morning?","Does she enjoy travel?","Has she ever had a busy week?"],"competency":"n2.information","score_weight":20},{"kind":"single","label":"Counter-hypothesis","new_data":"No manic episode is found despite detailed history and collateral information.","prompt":"Which competing hypothesis becomes much less likely?","choices":["Bipolar I disorder","Bipolar II disorder","Major depressive episode","Past hypomania"],"competency":"n2.differential","score_weight":15},{"kind":"final","label":"Conclusion","prompt":"Which longitudinal formulation is strongest?","diagnoses":["Recurrent major depressive disorder","Bipolar II disorder","Bipolar I disorder","Cyclothymic disorder"],"arguments":["Current depression only","Major depressive episode + characterized past hypomania + no history of mania","Presence of fatigue","Daily emotional lability"],"competency":"n2.formulation","score_weight":25}]}}'::jsonb,'{"steps":[{"kind":"multi","correct":[0,1],"weight":20,"calibration":4},{"kind":"single","correct":0,"weight":20,"calibration":4},{"kind":"single","correct":0,"weight":20,"calibration":4},{"kind":"single","correct":0,"weight":15,"calibration":3},{"kind":"final","diagnosis":1,"argument":1,"certainty_target":90,"weight":25}]}'::jsonb,100) on conflict(template_id) do update set course_key=excluded.course_key,content=excluded.content,answer_key=excluded.answer_key,max_score=excluded.max_score;

insert into public.challenge_templates(template_id,course_key,content,answer_key,max_score) values (3,'bipolar','{"fr":{"title":"Labilité n’est pas bipolarité","intro":"Un patient de 27 ans décrit depuis plusieurs années des changements d’humeur rapides, souvent après une remarque, un conflit ou une déception. Il demande s’il est « bipolaire ».","steps":[{"kind":"multi","label":"Première impression","prompt":"Quelles deux pistes doivent rester ouvertes au départ ?","choices":["Trouble bipolaire avec épisodes thymiques","Labilité émotionnelle réactive relevant d’un autre cadre psychopathologique","Manie certaine","Cause neurologique certaine"],"required":2,"max":2,"competency":"n2.branching","score_weight":20},{"kind":"single","label":"Temporalité","new_data":"Les changements surviennent en quelques minutes ou heures, sont fortement liés aux événements interpersonnels, et ne s’accompagnent pas de périodes soutenues de diminution du besoin de sommeil ou d’augmentation persistante de l’énergie.","prompt":"Quelle donnée affaiblit le plus l’hypothèse d’épisodes bipolaires typiques ?","choices":["Le caractère réactif et très bref des fluctuations sans changement soutenu d’énergie","L’existence de conflits","Le jeune âge","Le fait qu’il utilise le mot “humeur”"],"competency":"n2.causality","score_weight":20},{"kind":"single","label":"Question stratégique","prompt":"Quelle question serait la plus utile pour rechercher malgré tout une bipolarité méconnue ?","choices":["Existe-t-il des périodes distinctes de plusieurs jours avec changement net d’énergie, de sommeil, d’activité et de fonctionnement ?","Change-t-il souvent d’avis sur ses loisirs ?","Préfère-t-il être seul après un conflit ?","A-t-il déjà été triste après une rupture ?"],"competency":"n2.information","score_weight":20},{"kind":"single","label":"Contre-hypothèse","new_data":"Aucune période épisodique autonome de plusieurs jours n’est retrouvée, y compris auprès d’un proche.","prompt":"Quelle erreur de raisonnement faut-il surtout éviter ?","choices":["Assimiler toute instabilité émotionnelle à une bipolarité","Considérer la temporalité","Rechercher un état de base","Utiliser des informations collatérales"],"competency":"n2.closure","score_weight":15},{"kind":"final","label":"Conclusion","prompt":"Quelle conclusion est la plus rigoureuse à ce stade ?","diagnoses":["Trouble bipolaire I certain","Trouble bipolaire II certain","Bipolarité non établie ; labilité émotionnelle réactive nécessitant un différentiel plus large","Aucun problème clinique"],"arguments":["Les changements d’humeur sont fréquents","Absence d’épisodes soutenus et autonomes avec modification durable de l’énergie et du fonctionnement","Le patient est jeune","Les conflits sont présents"],"competency":"n2.formulation","score_weight":25}]},"en":{"title":"Lability is not bipolarity","intro":"A 27-year-old patient reports years of rapid mood changes, often following criticism, conflict or disappointment. He asks whether he is “bipolar”.","steps":[{"kind":"multi","label":"First impression","prompt":"Which two possibilities should remain open initially?","choices":["Bipolar disorder with mood episodes","Reactive emotional lability within another psychopathological framework","Definite mania","Definite neurological cause"],"required":2,"max":2,"competency":"n2.branching","score_weight":20},{"kind":"single","label":"Temporality","new_data":"Changes occur within minutes or hours, are strongly linked to interpersonal events, and are not accompanied by sustained periods of reduced need for sleep or persistent increased energy.","prompt":"Which finding most weakens the hypothesis of typical bipolar episodes?","choices":["Reactive, very brief fluctuations without sustained energy change","Presence of conflict","Young age","Use of the word “mood”"],"competency":"n2.causality","score_weight":20},{"kind":"single","label":"Strategic question","prompt":"Which question is most useful for still checking for overlooked bipolarity?","choices":["Have there been distinct periods lasting several days with clear changes in energy, sleep, activity and functioning?","Does he often change hobbies?","Does he prefer being alone after conflict?","Has he ever felt sad after a breakup?"],"competency":"n2.information","score_weight":20},{"kind":"single","label":"Counter-hypothesis","new_data":"No autonomous multi-day episodic period is found, including from collateral history.","prompt":"Which reasoning error should be avoided?","choices":["Equating all emotional instability with bipolarity","Considering temporality","Establishing a baseline","Using collateral information"],"competency":"n2.closure","score_weight":15},{"kind":"final","label":"Conclusion","prompt":"What is the most rigorous conclusion at this stage?","diagnoses":["Definite bipolar I disorder","Definite bipolar II disorder","Bipolarity is not established; reactive emotional lability requires a broader differential","No clinical issue"],"arguments":["Mood changes are frequent","No sustained autonomous episodes with durable change in energy and functioning","The patient is young","Conflicts are present"],"competency":"n2.formulation","score_weight":25}]}}'::jsonb,'{"steps":[{"kind":"multi","correct":[0,1],"weight":20,"calibration":4},{"kind":"single","correct":0,"weight":20,"calibration":4},{"kind":"single","correct":0,"weight":20,"calibration":4},{"kind":"single","correct":0,"weight":15,"calibration":3},{"kind":"final","diagnosis":2,"argument":1,"certainty_target":85,"weight":25}]}'::jsonb,100) on conflict(template_id) do update set course_key=excluded.course_key,content=excluded.content,answer_key=excluded.answer_key,max_score=excluded.max_score;

insert into public.challenge_templates(template_id,course_key,content,answer_key,max_score) values (4,'bipolar','{"fr":{"title":"Premier épisode tardif","intro":"Un patient de 63 ans, sans épisode thymique antérieur connu, présente depuis dix jours une activation nette avec réduction du besoin de sommeil, augmentation de l’activité, irritabilité et décisions inhabituelles.","steps":[{"kind":"multi","label":"Première impression","prompt":"Quelles deux branches doivent être activement examinées ?","choices":["Épisode maniaque primaire","Cause secondaire médicale ou médicamenteuse","Trouble bipolaire I certain d’emblée","Simple réaction de personnalité"],"required":2,"max":2,"competency":"n2.branching","score_weight":20},{"kind":"single","label":"Nouvelle donnée","new_data":"Il s’agit du premier épisode de ce type à 63 ans et un nouveau traitement a été débuté récemment pour une affection somatique.","prompt":"Quelle opération diagnostique devient prioritaire ?","choices":["Documenter systématiquement les causes secondaires et la temporalité des expositions","Conclure immédiatement à un trouble bipolaire I","Ignorer les traitements somatiques","Se limiter à quantifier l’irritabilité"],"competency":"n2.causality","score_weight":20},{"kind":"single","label":"Question stratégique","prompt":"Quelle information a la plus grande valeur discriminante ?","choices":["Chronologie précise entre nouveau traitement, symptômes, modifications somatiques et évolution après adaptation thérapeutique","Profession exercée à 25 ans","Préférence alimentaire","Nombre d’enfants"],"competency":"n2.information","score_weight":20},{"kind":"single","label":"Contre-hypothèse","new_data":"Le syndrome maniforme est cliniquement net, mais l’étiologie reste ouverte.","prompt":"Quelle formulation évite le mieux une fermeture prématurée ?","choices":["Syndrome maniaque actuel ; étiologie primaire versus secondaire encore à déterminer","Trouble bipolaire I définitivement prouvé","Aucune manie puisqu’il existe une cause somatique possible","Trouble anxieux certain"],"competency":"n2.closure","score_weight":15},{"kind":"final","label":"Conclusion","prompt":"Quelle conclusion est la plus défendable avant la fin du bilan étiologique ?","diagnoses":["Trouble bipolaire I certain","Syndrome maniaque avec cause secondaire à rechercher activement avant d’attribuer une bipolarité primaire","Trouble anxieux généralisé","Absence de trouble thymique"],"arguments":["Premier épisode tardif + exposition récente imposent une exploration causale structurée","L’âge suffit à exclure toute bipolarité","L’irritabilité confirme une cause organique","Le sommeil réduit suffit à poser le type I"],"competency":"n2.formulation","score_weight":25}]},"en":{"title":"Late first episode","intro":"A 63-year-old patient with no known previous mood episode develops ten days of clear activation with reduced need for sleep, increased activity, irritability and unusual decisions.","steps":[{"kind":"multi","label":"First impression","prompt":"Which two branches require active evaluation?","choices":["Primary manic episode","Secondary medical or medication cause","Definite bipolar I disorder immediately","Simple personality reaction"],"required":2,"max":2,"competency":"n2.branching","score_weight":20},{"kind":"single","label":"New information","new_data":"This is the first such episode at age 63, and a new treatment was recently started for a medical condition.","prompt":"Which diagnostic operation becomes a priority?","choices":["Systematically document secondary causes and exposure temporality","Immediately conclude bipolar I disorder","Ignore medical treatments","Only quantify irritability"],"competency":"n2.causality","score_weight":20},{"kind":"single","label":"Strategic question","prompt":"Which information has the greatest discriminating value?","choices":["Precise timeline between the new treatment, symptoms, medical changes and course after treatment adjustment","Occupation at age 25","Food preferences","Number of children"],"competency":"n2.information","score_weight":20},{"kind":"single","label":"Counter-hypothesis","new_data":"The manic syndrome is clinically clear, but etiology remains open.","prompt":"Which formulation best avoids premature closure?","choices":["Current manic syndrome; primary versus secondary etiology still to be determined","Bipolar I disorder definitively proven","No mania because a medical cause is possible","Definite anxiety disorder"],"competency":"n2.closure","score_weight":15},{"kind":"final","label":"Conclusion","prompt":"What is the most defensible conclusion before etiological assessment is complete?","diagnoses":["Definite bipolar I disorder","Manic syndrome with secondary causes requiring active investigation before attributing primary bipolarity","Generalized anxiety disorder","No mood disorder"],"arguments":["Late first episode plus recent exposure require structured causal investigation","Age alone excludes bipolarity","Irritability proves an organic cause","Reduced sleep alone establishes bipolar I"],"competency":"n2.formulation","score_weight":25}]}}'::jsonb,'{"steps":[{"kind":"multi","correct":[0,1],"weight":20,"calibration":4},{"kind":"single","correct":0,"weight":20,"calibration":4},{"kind":"single","correct":0,"weight":20,"calibration":4},{"kind":"single","correct":0,"weight":15,"calibration":3},{"kind":"final","diagnosis":1,"argument":0,"certainty_target":90,"weight":25}]}'::jsonb,100) on conflict(template_id) do update set course_key=excluded.course_key,content=excluded.content,answer_key=excluded.answer_key,max_score=excluded.max_score;



-- V52 challenge selector: choose a real template id by ordered offset rather than assuming contiguous ids.
create or replace function public.get_current_challenge(p_course_key text default 'bipolar')
returns table(challenge_key text,starts_at timestamptz,ends_at timestamptz,content jsonb)
language plpgsql security definer set search_path=public as $$
declare v_count int;v_id int;v_offset int;v_start timestamptz;v_content jsonb;
begin
 if auth.uid() is null then raise exception 'Authentication required'; end if;
 select count(*) into v_count from public.challenge_templates where course_key=p_course_key;
 if v_count=0 then return; end if;
 v_start:=date_trunc('week',now());v_offset:=(extract(week from v_start)::int % v_count);
 select ct.template_id into v_id
 from public.challenge_templates ct
 where ct.course_key=p_course_key
 order by ct.template_id
 offset v_offset limit 1;
 select c.content into v_content from public.challenge_templates c where c.course_key=p_course_key and c.template_id=v_id;
 challenge_key:=p_course_key||'-'||to_char(v_start,'IYYY-IW');starts_at:=v_start;ends_at:=v_start+interval '7 days';content:=v_content;return next;
end;$$;
revoke all on function public.get_current_challenge(text) from public;
grant execute on function public.get_current_challenge(text) to authenticated;

drop function if exists public.submit_weekly_challenge(text,jsonb);
create function public.submit_weekly_challenge(p_challenge_key text,p_answers jsonb)
returns table(score integer,accepted boolean,breakdown jsonb)
language plpgsql security definer set search_path=public as $$
declare
 v_uid uuid:=auth.uid();
 v_start timestamptz:=date_trunc('week',now());
 v_expected_key text;v_count int;v_id int;v_offset int;v_key jsonb;v_i int;v_existing int;
 v_expected jsonb;v_answer jsonb;v_kind text;v_weight int;v_cal int;v_correct int;v_choice int;v_conf int;
 v_points int;v_score int:=0;v_selected jsonb;v_correct_arr jsonb;v_overlap int;v_diag int;v_arg int;v_target int;v_diff int;
 v_stages jsonb:='[]'::jsonb;
begin
 if v_uid is null then raise exception 'Authentication required'; end if;
 select count(*) into v_count from public.challenge_templates where course_key='bipolar';
 if v_count=0 then raise exception 'No challenge template'; end if;
 v_offset:=(extract(week from v_start)::int % v_count);
 select ct.template_id into v_id
 from public.challenge_templates ct
 where ct.course_key='bipolar'
 order by ct.template_id
 offset v_offset limit 1;
 v_expected_key:='bipolar-'||to_char(v_start,'IYYY-IW');
 if p_challenge_key<>v_expected_key then raise exception 'Challenge is not current'; end if;
 select answer_key into v_key from public.challenge_templates where course_key='bipolar' and template_id=v_id;
 if jsonb_typeof(p_answers)<>'array' or jsonb_array_length(p_answers)<>jsonb_array_length(v_key->'steps') then raise exception 'Incomplete challenge'; end if;
 select ca.score into v_existing from public.challenge_attempts ca where ca.user_id=v_uid and ca.challenge_key=p_challenge_key;
 if v_existing is not null then score:=v_existing;accepted:=false;breakdown:=jsonb_build_object('stages','[]'::jsonb);return next;return;end if;

 for v_i in 0..jsonb_array_length(p_answers)-1 loop
   v_expected:=v_key->'steps'->v_i;v_answer:=p_answers->v_i;v_kind:=v_expected->>'kind';v_weight:=coalesce((v_expected->>'weight')::int,20);v_cal:=coalesce((v_expected->>'calibration')::int,0);v_points:=0;
   if v_kind='multi' then
     v_selected:=coalesce(v_answer->'selected','[]'::jsonb);v_correct_arr:=coalesce(v_expected->'correct','[]'::jsonb);v_conf:=greatest(0,least(coalesce((v_answer->>'confidence')::int,70),100));
     if jsonb_typeof(v_selected)<>'array' then raise exception 'Invalid multi answer'; end if;
     if v_selected @> v_correct_arr and v_correct_arr @> v_selected then
       v_points:=v_weight-v_cal;
       v_points:=v_points+case when v_conf>=80 then v_cal when v_conf>=60 then greatest(1,v_cal-1) else greatest(1,v_cal-2) end;
     else
       select count(*) into v_overlap from jsonb_array_elements_text(v_selected) s where exists(select 1 from jsonb_array_elements_text(v_correct_arr) c where c.value=s.value);
       if v_overlap>0 then v_points:=greatest(v_points,(v_weight-v_cal)/2); end if;
       if v_conf<=55 then v_points:=v_points+greatest(1,v_cal-1); elsif v_conf<=70 then v_points:=v_points+greatest(0,v_cal-2); end if;
     end if;
   elsif v_kind='single' then
     v_choice:=coalesce((v_answer->>'choice')::int,-1);v_correct:=(v_expected->>'correct')::int;v_conf:=greatest(0,least(coalesce((v_answer->>'confidence')::int,70),100));
     if v_choice=v_correct then
       v_points:=v_weight-v_cal;
       v_points:=v_points+case when v_conf>=80 then v_cal when v_conf>=60 then greatest(1,v_cal-1) else greatest(1,v_cal-2) end;
     else
       v_points:=case when v_conf<=55 then greatest(1,v_cal-1) when v_conf<=70 then greatest(0,v_cal-2) else 0 end;
     end if;
   elsif v_kind='final' then
     v_diag:=coalesce((v_answer->>'diagnosis')::int,-1);v_arg:=coalesce((v_answer->>'argument')::int,-1);v_conf:=greatest(0,least(coalesce((v_answer->>'confidence')::int,70),100));v_target:=coalesce((v_expected->>'certainty_target')::int,80);
     if v_diag=(v_expected->>'diagnosis')::int then v_points:=v_points+10; end if;
     if v_arg=(v_expected->>'argument')::int then v_points:=v_points+8; end if;
     v_diff:=abs(v_conf-v_target);
     v_points:=v_points+case when v_diff<=5 then 7 when v_diff<=15 then 4 when v_diff<=25 then 2 else 0 end;
   else
     raise exception 'Unsupported challenge step';
   end if;
   v_points:=greatest(0,least(v_points,v_weight));v_score:=v_score+v_points;v_stages:=v_stages||jsonb_build_array(v_points);
 end loop;
 v_score:=greatest(0,least(v_score,100));
 insert into public.challenge_attempts(user_id,challenge_key,course_key,score,answers) values(v_uid,p_challenge_key,'bipolar',v_score,p_answers);
 score:=v_score;accepted:=true;breakdown:=jsonb_build_object('stages',v_stages);return next;
end;$$;
revoke all on function public.submit_weekly_challenge(text,jsonb) from public;
grant execute on function public.submit_weekly_challenge(text,jsonb) to authenticated;
